// Regenerates `livingDocs/common/abstractFont.ts` from the bundled woff2 files.
//
// Why a generated file exists at all: the product's mono has to render in three places, and only one of
// them can load a font by URL. The workbench chrome is a normal document, so its stylesheet reaches the
// woff2 with a relative `url()`. The two webviews are separate documents on a different origin with a
// restrictive CSP, so a relative URL resolves to nothing there. Inlining the bytes as a `data:` URI is
// the one delivery that works in all three, and a TypeScript constant is the only form both webviews can
// import. The woff2 files under `livingDocs/browser/media/fonts/` remain the source of truth; this script
// just re-encodes them.
//
// Run with: node --experimental-strip-types build/lib/generate-abstract-font.ts

import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const fontDir = path.join(root, 'src', 'vs', 'workbench', 'contrib', 'livingDocs', 'browser', 'media', 'fonts');
const out = path.join(root, 'src', 'vs', 'workbench', 'contrib', 'livingDocs', 'common', 'abstractFont.ts');

const weights = [
	{ weight: 400, file: 'ibm-plex-mono-latin-400.woff2' },
	{ weight: 600, file: 'ibm-plex-mono-latin-600.woff2' },
];

const faces = weights.map(w => {
	const bytes = fs.readFileSync(path.join(fontDir, w.file));
	return { ...w, b64: bytes.toString('base64'), size: bytes.length };
});

const header = `/*---------------------------------------------------------------------------------------------
 *  Copyright (c) Microsoft Corporation. All rights reserved.
 *  Licensed under the MIT License. See License.txt in the project root for license information.
 *--------------------------------------------------------------------------------------------*/

// GENERATED by build/lib/generate-abstract-font.ts from browser/media/fonts/*.woff2 - do not edit by hand.
//
// IBM Plex Mono, latin subset, weights 400 and 600, as \`data:\` URIs. The design system reserves mono for
// section labels, kind badges and provenance facts (file names, cells, synced-when, line numbers), so the
// latin subset covers every character the product actually sets in it - about 10KB per weight.
//
// The bytes are inlined rather than linked because the two webviews are separate documents on a different
// origin: a relative \`url()\` in their inlined stylesheet resolves to nothing, and they have no
// \`localResourceRoots\` configured. A \`data:\` URI is the one form that renders in the webviews AND in the
// workbench chrome. See \`browser/media/fonts/LICENSE.txt\` - IBM Plex is SIL OFL 1.1, which permits this.

/** The \`@font-face\` block every Abstract surface inlines so its mono is the real IBM Plex Mono. */
export const ABSTRACT_FONT_FACE_CSS = \`${faces.map(f => `@font-face{font-family:'IBM Plex Mono';font-style:normal;font-weight:${f.weight};font-display:swap;src:url(data:font/woff2;base64,${f.b64}) format('woff2')}`).join('\n')}\`;
`;

fs.writeFileSync(out, header);
console.log(`wrote ${out}`);
for (const f of faces) {
	console.log(`  weight ${f.weight}: ${f.size} bytes -> ${f.b64.length} base64 chars`);
}
